INSERT INTO "localized_texts" ("id", "tbl_name", "tbl_column_name", "idx", "ko", "ko_ver", "en_us", "en_us_ver", "zh_cn", "zh_cn_ver", "ja", "ja_ver", "ru", "ru_ver", "zh_tw", "zh_tw_ver", "de", "de_ver", "fr", "fr_ver") SELECT 317985, 'items', 'name', 45311, '패왕의 품격', 0, 'Werefox Robes', 0, '', 0, '', 0, '', 0, '', 0, '', 0, '', 0 WHERE NOT EXISTS (SELECT 1 FROM "localized_texts" WHERE "id" = 317985);
INSERT INTO "localized_texts" ("id", "tbl_name", "tbl_column_name", "idx", "ko", "ko_ver", "en_us", "en_us_ver", "zh_cn", "zh_cn_ver", "ja", "ja_ver", "ru", "ru_ver", "zh_tw", "zh_tw_ver", "de", "de_ver", "fr", "fr_ver") SELECT 317986, 'items', 'description', 45490, '', 0, 'Originating in the court of Empress Pavitra during her long campaign to unite Haranya, the Wartime Nobility aesthetic featured luxurious materials and styling accented by symbolic pieces of ornate armor. The fashion became wildly popular throughout the kingdom, even amongst those who had never seen a battle in their lives--but it is safe to assume that for the empress and her generals, at least, the costumes were far from merely decorative.', 0, '', 0, '', 0, '', 0, '', 0, '', 0, '', 0 WHERE NOT EXISTS (SELECT 1 FROM "localized_texts" WHERE "id" = 317986);
